def create_curators(apps, schema_editor):
    """Переносит ФИО/телефон кураторов из полей GroupModel в CuratorModel.

    Страница-справочник кураторов создаётся при необходимости с явными
    полями дерева (как в 0007_convert_snippets_to_pages).
    """
    db_alias = schema_editor.connection.alias

    ContentType = apps.get_model("contenttypes", "ContentType")
    Locale = apps.get_model("wagtailcore", "Locale")
    Page = apps.get_model("wagtailcore", "Page")
    CuratorPage = apps.get_model("home", "CuratorPage")
    CuratorModel = apps.get_model("home", "CuratorModel")
    GroupModel = apps.get_model("home", "GroupModel")

    groups = (
        GroupModel.objects.using(db_alias)
        .exclude(curator_name="")
        .order_by("pk")
    )
    if not groups.exists():
        return

    page = CuratorPage.objects.using(db_alias).first()
    if page is None:
        locale = Locale.objects.using(db_alias).first()
        if locale is None:
            locale = Locale.objects.using(db_alias).create(language_code="en-us")

        root = Page.objects.using(db_alias).filter(depth=2).order_by("path").first()
        if root is None:
            return

        content_type, _ = ContentType.objects.using(db_alias).get_or_create(
            app_label="home", model="curatorpage"
        )
        used_slugs = set(
            Page.objects.using(db_alias)
            .filter(path__startswith=root.path, depth=root.depth + 1)
            .values_list("slug", flat=True)
        )
        slug = "curators"
        suffix = 2
        while slug in used_slugs:
            slug = f"curators-{suffix}"
            suffix += 1
        path_suffix = root.numchild + 1
        page = CuratorPage(
            title="Кураторы",
            draft_title="Кураторы",
            slug=slug,
            content_type=content_type,
            locale=locale,
            translation_key=uuid.uuid4(),
            path=root.path + "%04d" % path_suffix,
            depth=root.depth + 1,
            numchild=0,
            url_path=root.url_path + slug + "/",
            live=True,
            has_unpublished_changes=False,
            expired=False,
            locked=False,
            show_in_menus=False,
            seo_title="",
            search_description="",
        )
        page.save(using=db_alias)
        Page.objects.using(db_alias).filter(pk=root.pk).update(numchild=path_suffix)

    curator_pks = {}
    for group in groups:
        key = (group.curator_name.strip(), (group.curator_phone or "").strip())
        if key not in curator_pks:
            curator = CuratorModel.objects.using(db_alias).create(
                curator_page=page,
                name=key[0],
                phone=key[1],
            )
            curator_pks[key] = curator.pk
        group.curator_id = curator_pks[key]
        group.save(using=db_alias)


